#!/usr/bin/env python3
"""Build the reviewed 2026-09-01 through 2026-09-15 lesson content files."""

from __future__ import annotations

import json
import re
from copy import deepcopy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GENERATOR = ROOT / "generator"


def ruby(text: str) -> str:
    return re.sub(r"\[([^]|]+)\|([^]]+)\]", r"<ruby>\1<rt>\2</rt></ruby>", text)


def vocab(surface: str, reading: str, meaning: str, components: list[tuple[str, str, str]] | None = None) -> dict:
    item = {"surface": surface, "reading": reading, "meaningZh": meaning, "pitch": None, "pitchVerified": False}
    if components:
        item["components"] = [vocab(*part) for part in components]
    return item


def make_lesson(spec: dict, number: int) -> dict:
    words = [vocab(*item) for item in spec["vocab"]]
    custom = [{"japaneseHtml": ruby(ja), "translationZh": zh} for ja, zh in spec["sentences"]]
    common = [
        ("この[話題|わだい]を一つの[情報|じょうほう]だけで[判断|はんだん]しません。", "不只憑單一資訊判斷這個話題。"),
        ("[複数|ふくすう]の[見方|みかた]を[比|くら]べます。", "比較多種觀點。"),
        ("[背景|はいけい]を[踏|ふ]まえて[判断|はんだん]します。", "根據背景作判斷。"),
        ("[誤解|ごかい]しないように、[出典|しゅってん]と[日付|ひづけ]を[確認|かくにん]します。", "為避免誤解而確認來源與日期。"),
        ("[関心|かんしん]の[高|たか]まりに[伴|ともな]って、[説明|せつめい]も[必要|ひつよう]になります。", "隨關注升高，說明也變得必要。"),
        ("[自分|じぶん]の[意見|いけん]を[短|みじか]く[伝|つた]えます。", "簡短表達自己的意見。"),
    ]
    useful = custom + [{"japaneseHtml": ruby(ja), "translationZh": zh} for ja, zh in common]
    review_patterns = ["〜ように", "〜を踏まえて", "〜に伴って"]
    review = review_patterns[number % 3]
    return {
        "templateVersion": "Japanese Lesson Template V1",
        "lesson": {
            "id": spec["id"], "date": spec["date"], "topicJa": spec["topicJa"], "topicZh": spec["topicZh"],
            "summaryZh": spec["summary"], "jlptLevel": "N3→N2", "duration": "25–35 分鐘",
            "domain": spec["domain"], "trendSource": spec["source"],
        },
        "reading": {
            "leadZh": spec["lead"], "japaneseHtml": ruby(spec["reading"]), "translationZh": spec["translation"],
            "pronunciation": [deepcopy(words[0])], "readingVocabulary": deepcopy(words),
        },
        "usefulSentences": useful,
        "vocabulary": deepcopy(words),
        "patterns": [
            {"name": spec["pattern"][0], "formation": spec["pattern"][1], "explanationZh": spec["pattern"][2],
             "example": {"japaneseHtml": ruby(spec["pattern"][3]), "translationZh": spec["pattern"][4]}},
            {"name": "〜ように／〜を踏まえて", "formation": "動詞普通形＋ように／名詞＋を踏まえて",
             "explanationZh": "分別表示目的、避免，以及將依據納入判斷。",
             "example": {"japaneseHtml": ruby("[状況|じょうきょう]を[踏|ふ]まえて、[間違|まちが]えないように[確認|かくにん]します。"), "translationZh": "依情況判斷，並為避免錯誤而確認。"}},
        ],
        "quiz": [
            {"id": "q1", "type": "singleChoice", "promptZh": spec["question"], "choices": [
                {"value": "A", "labelHtml": "A. " + spec["choices"][0]}, {"value": "B", "labelHtml": "B. " + spec["choices"][1]}]},
            {"id": "q2", "type": "text", "promptZh": "填空：背景を（　）まえて判断します。"},
            {"id": "q3", "type": "textarea", "promptZh": "用「〜ように」寫一句與本課主題有關的目的或提醒。"},
            {"id": "q4", "type": "textarea", "promptZh": "用「〜に伴って」說明本課議題的一項變化。"},
        ],
        "outputPractice": {"promptZh": spec["output"], "exampleJaHtml": ruby(spec["outputExample"]), "maxLength": 650},
        "previousReview": {
            "pattern": review, "explanationZh": "把既有弱點句型放回新情境，確認能自行產出。",
            "exampleJaHtml": ruby("[情報|じょうほう]を[踏|ふ]まえて、[誤解|ごかい]しないように[説明|せつめい]します。"),
            "promptZh": f"請用「{review}」另造一句，內容不可照抄範例。",
        },
        "weaknessRecovery": ["〜を踏まえて", "〜ように（目的／提醒）", "〜に伴って", spec["skill"], "閱讀理解", "短篇自由輸出"],
    }


