def write_content(path: Path, week: str, lessons: list[dict], partial: bool = False) -> None:
    data = {"templateVersion": "Japanese Lesson Template V1", "week": week,
            "contentPolicy": "2026-09-01 即時題材研究後原創；正文不複製貼文、榜單、摘要或新聞原文。",
            "lessons": lessons}
    if partial:
        data["partialWeek"] = True
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")


def main() -> None:
    built = [make_lesson(spec, index) for index, spec in enumerate(SPECS, 1)]
    old = json.loads((GENERATOR / "weekly-content-2026-W36-partial.json").read_text(encoding="utf-8"))["lessons"][0]
    old["lesson"]["trendSource"] = "nikkei"
    write_content(GENERATOR / "weekly-content-2026-W36.json", "2026-W36", [old, *built[:6]])
    write_content(GENERATOR / "weekly-content-2026-W37.json", "2026-W37", built[6:13])
    write_content(GENERATOR / "weekly-content-2026-W38-partial.json", "2026-W38", built[13:], partial=True)
    print("Built W36 (7), W37 (7), W38 partial (2).")


if __name__ == "__main__":
    main()
